        { 92753, "A", 9, 18, "阿尔巴·晴月", "西部荒野 52.4,53", nil, false, {92752}, nil, "找到深藏于死亡矿井中的熔炉，在旁安放强效炸药；随后在死亡矿井出口与阿尔巴·晴月会合。", "本链的副本段：进本前炸药已由爆炸物筹备段（斯普莱特 → 贾斯伯·菲尔）备齐。安放炸药后从副本出口出来，到月溪镇后方的山丘与阿尔巴·晴月会合。◎ 熔炉即吉尔尼德所在的房间，靠近中央安放炸药；跑完这段别用炉石——从副本后门出去，在后门入口继续任务。", {{9,1}, {14,2}, {16,3}, {21,4}, {25,5}}, nil, nil, 253092, "阿尔巴·晴月", { xp = 4050, rep = { {72, 50, "暴风城"} } } },
        { 92819, "A", 9, 18, "阿尔巴·晴月", "西部荒野 - 月溪镇后方山丘 38.6,83.2", "爆破死亡矿井", false, {92753}, nil, "使用遥控起爆器，引爆安放在熔炉旁的炸药。", "「爆破死亡矿井」的收尾环：与月溪镇后方山丘的阿尔巴·晴月会合后，使用起爆器收尾。", {{9,1}, {14,2}, {16,3}, {21,4}, {25,5}}, nil, nil, 253279, "阿尔巴·晴月", { rep = { {72, 50, "暴风城"} } } },
        { 166, "A", 14, 22, "格里安·斯托曼", "西部荒野 - 哨兵岭 56,47", "迪菲亚兄弟会", false, {155}, {6087, 2041, 2042}, "击杀艾德温·范克里夫，把他的头颅带回去交给格里安·斯托曼。", "整个系列从格里安·斯托曼（西部荒野 - 哨兵岭 56,47）开始。范克里夫是死亡矿井的最终 首领，在船的最上层。", {{14,1}, {18,2}, {20,3}, {25,4}, {29,5}}, {3637}, nil, 234, "格里安·斯托曼", { xp = 2600, rep = { {72, 200, "暴风城"} } } },
        { 168, "A", 14, 18, "维尔德·蓟草", "暴风城 - 矮人区 70,41", nil, false, nil, {2037, 2036, 270007}, "收集 4 张矿业工会会员卡，交给暴风城的维尔德·蓟草。", "会员卡由副本入口附近的亡灵掉落。◎ 会员卡掉率很低且不共享（各拾各的），实测耗时较长，做好心理准备。", {{14,2}, {16,3}, {21,4}, {25,5}}, {1894}, nil, 656, "维尔德·蓟草", { xp = 1350, rep = { {47, 100, "铁炉堡"} } } },
        { 214, "A", 14, 17, "哨兵瑞尔", "西部荒野 - 哨兵岭 56, 47", "迪菲亚兄弟会", false, {155}, {2074, 2089, 6094, 270005}, "收集 10 条红色丝质面罩，交给哨兵岭哨塔的哨兵瑞尔。", "副本内外的矿工都会掉面罩。要先完成「护送迪菲亚叛徒」才会开放这个任务。", {{14,2}, {15,3}, {20,4}, {24,5}}, {915}, nil, 820, "哨兵瑞尔", { xp = 1250, rep = { {72, 100, "暴风城"} } } },
        { 167, "A", 15, 20, "维尔德·蓟草", "暴风城 - 矮人区 70,41", nil, false, nil, {1893, 270012, 270013}, "取回探险者协会徽章，交给暴风城的维尔德·蓟草。", "徽章由副本入口处的工头希斯奈特掉落。◎ 单刷建议 23 级以上：精英伤害高且会连锁拉怪，任务目标怪与旁边一只小怪联动。", {{15,1}, {16,2}, {18,3}, {23,4}, {27,5}}, {1875}, nil, 656, "维尔德·蓟草", { xp = 1550, money = 500, rep = { {47, 100, "铁炉堡"} } } },
        { 2040, "A", 15, 20, "沉默的舒尼", "暴风城 - 矮人区 62,34", "沉默的舒尼", false, {2041}, {7606, 7607, 270015, 270016}, "从死亡矿井带回小型高能发动机，交给暴风城矮人区的沉默的舒尼。", "这个任务可以直接接，也可以先做诺恩（铁炉堡 - 侏儒区 69,50）给的引导任务。发动机由斯尼德的伐木机掉落。", {{15,1}, {16,2}, {18,3}, {23,4}, {27,5}}, {7365}, nil, 6579, "沉默的舒尼", { xp = 1550, rep = { {72, 100, "暴风城"}, {54, 100, "诺莫瑞根流亡者"} } } },
        { 373, nil, 16, nil, nil, "未寄出的信掉落自（艾德温·范克里夫）", nil, false, nil, nil, "搜查艾德温·范克里夫的尸体，找到一封没来得及寄出的信——收信人是暴风城石工协会的巴隆斯·阿历克斯顿。", "巴隆斯·阿历克斯顿在暴风城大教堂旁（58,49）。", {{16,1}, {18,2}, {20,3}, {25,4}, {29,5}}, {2874}, nil, nil, nil, nil },
        { 1654, nil, 20, nil, "乔丹·斯迪威尔", "丹莫罗 - 铁炉堡 52,36", "正义试炼", false, {1653}, nil, "按乔丹的武器材料单备齐白石橡木、精炼矿石、乔丹的铁锤和科尔宝石，回铁炉堡见乔丹·斯迪威尔。", "材料明细点开 [乔丹的武器材料单] 可以看到。", {{20,3}, {25,4}, {29,5}}, {6994, 6993, 6895, 7083, 6996}, "圣骑士", 6181, "乔丹·斯迪威尔", nil },
