    ["shadowfang_keep"] = {
        { 1013, "H", 16, 26, "看守者贝尔杜加", "幽暗城 - 炼金房 53,54", nil, false, nil, {6335, 4534, 270030}, "把乌尔之书带给幽暗城炼金区的看守者贝尔杜加。", "书在芬鲁斯（巨狼）房间的书架上——进房间左手边第一个书架下层，蓝色书本。◎ 拾取后约 10 秒重生，全队每人都能拿到（不共享）。◎ 杀死芬鲁斯后他会召唤 4 只虚空行者（非精英但伤害不低，盗贼/野德可提前脱战隐身）。", {{16,1}, {22,2}, {24,3}, {29,4}, {34,5}}, {6283}, nil, 2934, "看守者贝尔杜加", { xp = 2100, money = 1400, rep = { {68, 100, "幽暗城"} } } },
