    ["excavation_wetlands"] = {
        { 95772, nil, 24, 31, "多林·桑布雷德", "赤脊山 - 湖畔镇 25.6,46.6", nil, false, nil, nil, "到维尔加挖掘场一带寻找多林·桑布雷德的兄弟戴温。", "戴温随勘探队进了挖掘场，之后能在副本内他的遗体上接到后续任务。◎ 发布者在湖畔镇的马厩里——从飞行点过桥后左手边（玩家实测）。", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, nil, nil, 956, "多林·桑布雷德", { xp = 3150 } },
        { 98815, nil, 24, 28, "詹姆斯·哈洛兰", "湿地 - 米奈希尔港 8,55", "日常供货", false, {469}, nil, "把 4 张灌木丛迅猛龙皮交给米奈希尔港的制皮匠詹姆斯·哈洛兰。", "迅猛龙皮由挖掘场的迅猛龙类掉落；前置是哈洛兰的「幼鳄鱼皮」，无需先做「日常供货」（玩家实测，与 Wowhead 表格口径矛盾）。", {{24,2}, {26,3}, {31,4}, {36,5}}, nil, nil, 2094, "詹姆斯·哈洛兰", { xp = 1150, money = 1200, rep = { {72, 50, "暴风城"} } } },
        { 95646, "A", 24, 31, "绿色守卫者雷希耶尔", "湿地 56.2,40.6", nil, false, nil, {271667, 271670, 271664}, "在挖掘场杀一只高地惊魂，把它的根核带给湿地的雷希耶尔。", "可怕的根核（#270180）由副本内的高地惊魂掉落，三选一奖励。◎ 前置：先完成菲茨西蒙斯大副（#1239）的湿地四步链——绿色守卫者(463)、践踏之足(276)、火之禁忌(277)、大地上的水泡(275)，之后才会给接本任务。", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {270180}, nil, 1244, "绿色守卫者雷希耶尔", { xp = 3150 } },
        { 95647, "A", 24, 31, "凯特林·格拉斯曼", "湿地 - 米奈希尔港南 11.6,58.4", "寻找凯特林", false, {95737}, nil, "在挖掘场找到阿尔丁·格拉斯曼，弄清他遭遇了什么。", "链从灰谷蓝纳（#3970，35.0,48.6）的「寻找凯特林」开始。", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, nil, nil, 1480, "凯特林·格拉斯曼", { xp = 2500 } },
        { 95795, "A", 24, 31, nil, nil, nil, true, nil, {271769, 271768}, "把戴温的命运带回湖畔镇告诉多林·桑布雷德。", "在副本内戴温的遗体上直接接取，腰甲二选一。", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, nil, nil, nil, nil, { xp = 3150 } },
        { 95697, "H", 24, 31, "博尔斯坦", "奥格瑞玛 - 暗巷区 57.5,53.4", nil, false, nil, {280766, 280805, 250185, 250077}, "进挖掘场带回 4 块灌木丛迅猛龙肉。", "肉（#271100）由副本内迅猛龙类掉落；发布者=烹饪训练师博尔斯坦（奥格瑞玛暗巷区，57.5,53.4）。奖励含烹饪食谱。", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {271100}, nil, 3368, "博尔斯坦", { xp = 3150 } },
        { 95664, "H", 24, 31, nil, nil, nil, false, nil, nil, "把泰坦圣物带到雷霆崖长者高地，找能鉴定它的人。", "打完尾王遗迹守卫者后拾取泰坦圣物（#270865），拾取即开启本任务；多名玩家证实（10/2）：上交时泰坦圣物不会归还。", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {270865}, nil, nil, nil, { xp = 630 } },
        { 95810, "A", 24, 31, nil, nil, nil, false, nil, nil, "把泰坦圣物带给湿地的勘察员维尔加。", "拾取泰坦圣物（#270865）开启；联盟方交给维尔加挖掘场的勘察员维尔加（#1077）。", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {270865}, nil, nil, nil, { xp = 630 } },
        { 95682, "H", 24, nil, "亡灵卫兵密探", "湿地 - 挖掘场入口旁的山丘", nil, false, nil, {271740, 271732, 271745}, "在挖掘场杀 2 名龙喉破坏者和 4 名龙喉守卫，带着战利品回到副本外的亡灵卫兵密探处。", "龙喉急件（#284844）由副本内龙喉单位掉落；发布者藏在入口区域旁的山丘里（已确认）。◎ 有玩家提示可先在落锤镇楼梯下的兽人（疑似扎鲁克）处接前置，待核实。", nil, {284844}, nil, 13155, "亡灵卫兵密探", nil },
        { 98823, "H", 24, nil, nil, nil, "长者知识", false, {95664}, {271766, 271767, 271719}, "把泰坦圣物带给莫高雷西北天空守望者高地的穆恩·大地之怒（Muln Earthfury）。", "「长者知识」的后续；圣物由尾王遗迹守卫者掉落（#270865）。◎ beta 已知 bug（10/2-10/3 实测）：上交「长者知识」时圣物被吞、本任务无法完成，弃任务后也无法重接。", nil, {270865}, nil, nil, nil, nil },
        { 95809, "A", 24, nil, nil, nil, "灌木丛里的东西", false, {95647}, {1710, 3827, 2459, 280766}, "把编草心带回米奈希尔港交给凯特林·格拉斯曼。", "完成「灌木丛里的东西」后阿尔丁给的信物编草心（#270901，Reed-woven Heart）开启本任务。", nil, {270901}, nil, nil, nil, nil },
        { 98824, "A", 24, nil, "勘察员维尔加", nil, "运送失落的圣物", false, {95810}, {271716, 271767, 271766}, "把泰坦圣物带给铁炉堡探险者大厅的高级探险家玛盖拉斯（High Explorer Magellas）。", "「运送失落的圣物」的后续，在勘察员维尔加（#1077）处接续；圣物由尾王遗迹守卫者掉落（#270865）。◎ 同系 bug（10/1-10/2 实测）：上交前一步丢失泰坦圣物，导致无法交付。", nil, {270865}, nil, 1077, "勘察员维尔加", nil },
