    ["razorfen_downs"] = {
        { 6521, "H", 28, 36, "瓦里玛萨斯", "幽暗城 - 皇家区 56,92", "邪恶的盟友", false, {6522}, {17039, 17042, 17043}, "把玛克林大使的头颅带给幽暗城的瓦里玛萨斯。", "前置由剃刀沼泽的最终首领给出。玛克林大使在进副本前的空地上（贫瘠之地 - 剃刀高地 48,92）。", {{28,1}, {32,2}, {34,3}, {39,4}, {45,5}}, {17009}, nil, 2425, "瓦里玛萨斯", { xp = 3500, money = 2000 } },
        { 6522, "H", 28, 36, "由物品[小卷轴]起始", nil, nil, false, nil, nil, nil, nil, {{28,1}, {32,2}, {34,3}, {39,4}, {45,5}}, {17008}, nil, nil, nil, { xp = 2800, money = 4000 } },
        { 6626, nil, 28, 35, "麦雷姆·月歌", "贫瘠之地 - 剃刀高地 49,94", nil, false, nil, nil, "杀 8 个剃刀沼泽护卫者、8 个剃刀沼泽织棘者和 8 个亡首教徒，向剃刀高地入口处的麦雷姆·月歌复命。", "这三种怪都在进副本前经过的路上。", {{28,1}, {31,2}, {33,3}, {38,4}, {44,5}}, nil, nil, 12866, "麦雷姆·月歌", { xp = 3450, money = 7500 } },
        { 3523, nil, 32, 37, "奔尼斯特拉兹", nil, nil, true, nil, nil, nil, "这不是护送任务本体——先完成它，之后才会开放真正的护送任务《扑灭圣火之仪》。确保全队都完成本任务后再进护送段，否则没完成的人拿不到后续。", {{32,1}, {33,2}, {35,3}, {40,4}, {46,5}}, {10682}, nil, 8516, "奔尼斯特拉兹", { xp = 285 } },
        { 3525, nil, 32, 37, "奔尼斯特拉兹", "剃刀高地", "剃刀高地的亡灵天灾", true, {3523}, {10710}, "陪奔尼斯特拉兹到剃刀高地的野猪人神像处，在他仪式封印神像时保护他。", "接受协助后仪式期间会不断刷怪攻击他，保证他不倒；完成后在神像前交付领奖。", {{32,1}, {33,2}, {35,3}, {40,4}, {46,5}}, nil, nil, 8516, "奔尼斯特拉兹", { xp = 4250 } },
