        { 1049, "H", 28, 38, "圣者图希克", "雷霆崖 34,47", nil, false, nil, {7747, 17508, 7749}, "从血色修道院取回《堕落者纲要》，交给雷霆崖的圣者图希克。", "书在图书馆区。被遗忘者因剧情原因接不了这个任务。", {{28,1}, {34,2}, {36,3}, {41,4}, {47,5}}, {5535}, nil, 3978, "圣者图希克", { xp = 3550, rep = { {81, 150, "雷霆崖"} } } },
        { 1050, "A", 28, 38, "图书馆员麦伊·苍尘", "铁炉堡 - 探险者大厅 74,12", nil, false, nil, {7746}, "从修道院取回《泰坦神话》，交给铁炉堡的图书馆员麦伊·苍尘。", "书在图书馆里奥法师杜安房间之前、左侧走廊的地板上。", {{28,1}, {34,2}, {36,3}, {41,4}, {47,5}}, {5536}, nil, 3979, "图书馆员麦伊·苍尘", { xp = 3550, rep = { {47, 150, "铁炉堡"} } } },
        { 1113, "H", 30, 33, "大药剂师法拉尼尔", "幽暗城 - 炼金房 48,69", "蝙蝠的粪便", false, {1109}, nil, "替幽暗城的大药剂师法拉尼尔收集 20 颗狂热之心。", "血色修道院里所有怪物都有几率掉。", {{30,2}, {31,3}, {36,4}, {42,5}}, {5805}, nil, 2055, "大药剂师法拉尼尔", { xp = 3300, rep = { {68, 150, "幽暗城"} } } },
        { 1048, "H", 33, 42, "瓦里玛萨斯", "幽暗城 - 皇家区 56,92", nil, false, nil, {6802, 6803, 10711}, "击杀大检察官怀特迈恩、血色十字军指挥官莫格莱尼、勇士赫洛德和驯犬者洛克希，回幽暗城向瓦里玛萨斯复命。", "怀特迈恩与莫格莱尼在教堂区，赫洛德在军械库，洛克希在图书馆。", {{33,1}, {38,2}, {40,3}, {45,4}, {52,5}}, nil, nil, 2425, "瓦里玛萨斯", { xp = 5150, rep = { {68, 200, "幽暗城"} } } },
        { 1053, "A", 34, 40, "虔诚的莱雷恩", "希尔斯布莱德丘陵 - 南海镇 51,58", "血色之路", false, {1052}, {6829, 6830, 6831, 11262}, "击杀大检察官怀特迈恩、指挥官莫格莱尼、勇士赫洛德和驯犬者洛克希，回南海镇向莱雷恩复命。", "系列始于克罗雷修士（暴风城 - 大教堂 52,43），也可从凄凉之地尼耶尔前哨站的血色十字军使者处直接接。三个目标位置：教堂（怀特迈恩、莫格莱尼）、军械库（赫洛德）、图书馆（洛克希）。", {{34,1}, {36,2}, {38,3}, {43,4}, {49,5}}, nil, nil, 3980, "虔诚的莱雷恩", { xp = 4700, rep = { {72, 200, "暴风城"} } } },
