    ["uldaman"] = {
        { 1192, nil, 29, nil, "普兹克", "千针石林 - 沙漠赛道 80.1, 75.9", "瑞兹尔的图表", false, {1194}, nil, "为千针石林的普兹克收集 4 块精铁矿石。", "前置完成后的可重复任务，只给少量金钱，无声望经验。矿石可在奥达曼内采矿获得，也能从玩家处买。", {{29,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {5833}, nil, 4630, "普兹克", nil },
        { 704, "A", 30, 38, "勘察员基恩萨·铁环", "洛克莫丹 - 铁环挖掘场 65,65", "莫达洛克", false, {739}, {4980}, "收集 4 个雕纹石罐，交给洛克莫丹的勘察员基恩萨·铁环。", "系列始于勘察员塔伯斯·雷矛（铁炉堡 - 探险者大厅 74,12）。石罐散落在副本前的山洞里。", {{30,1}, {34,2}, {36,3}, {41,4}, {47,5}}, {4610}, nil, 1344, "勘察员基恩萨·铁环", { xp = 2850, rep = { {47, 100, "铁炉堡"} } } },
        { 709, nil, 30, 40, "迷失者塞尔杜林", "荒芜之地 51,76", nil, false, nil, {4746}, "把雷乌纳石板带给迷失者塞尔杜林。", "石板在洞穴北端通道尽头。", {{30,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {4631}, nil, 2785, "迷失者塞尔杜林", { xp = 3150 } },
        { 2418, nil, 30, 36, "里格弗兹", "荒芜之地 42,52", nil, false, nil, {9522, 10358, 10359}, "为荒芜之地的里格弗兹收集 8 块德提亚姆能量石和 8 块安纳洛姆能量石。", "副本内外的暗炉系敌人都掉能量石。不用进副本——在进本前的挖掘场打暗炉矮人就能攒齐。", {{30,1}, {32,2}, {34,3}, {39,4}, {45,5}}, {8009, 8052}, nil, 2817, "里格弗兹", { xp = 3500, rep = { {21, 150, "藏宝海湾"}, {87, 750, "血帆海盗"} } } },
        { 1360, "A", 33, 43, "克罗姆·粗臂", "铁炉堡 - 探险者大厅 74,9", nil, false, nil, nil, "到奥达曼北部大厅找到克罗姆·粗臂的箱子，取出里面的财物，带回铁炉堡交给他。", "财物在进副本前的洞穴里，北面第一条通道东南角尽头。", {{33,1}, {39,2}, {41,3}, {46,4}, {53,5}}, {8027}, nil, 6294, "克罗姆·粗臂", { xp = 3600, money = 6000, rep = { {47, 100, "铁炉堡"} } } },
        { 2342, "H", 33, 43, "帕特里克·加瑞特", "幽暗城 72,48", nil, false, nil, nil, "从奥达曼南部大厅的箱子里找回加勒特的家族宝藏，交给幽暗城的帕特里克·加瑞特。", "宝藏进副本前就能拿到，在南部通道尽头。", {{33,1}, {39,2}, {41,3}, {46,4}, {53,5}}, {8026}, nil, 5651, "帕特里克·加瑞特", { xp = 3600, money = 6000, rep = { {68, 100, "幽暗城"} } } },
        { 721, nil, 35, nil, "勘察员雷杜尔", "荒芜之地 53,43", "一线希望", false, {720}, nil, "进入奥达曼找到铁趾格雷兹。", "系列始于一张弄皱的地图（荒芜之地 53,33）。铁趾格雷兹在副本入口附近。", {{35,3}, {38,4}, {44,5}}, nil, nil, 2910, "勘察员雷杜尔", nil },
        { 722, "A", 35, 40, "铁趾格雷兹", "奥达曼 副本入口地图）。", "一线希望", false, {721}, nil, "找回铁趾的护符，交给奥达曼的铁趾格雷兹。", "护符由马格雷甘·深影掉落。", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {4635}, nil, 2909, "铁趾格雷兹", { xp = 3150, rep = { {47, 100, "铁炉堡"} } } },
        { 1139, "A", 35, 45, "顾问贝尔格拉姆", "铁炉堡 - 探险者大厅 77,10", "邪恶的使者", false, {762}, {6723}, "找到意志石板，交给铁炉堡的顾问贝尔格拉姆。", "石板在副本内，就在加加恩·火锤身旁。", {{35,1}, {41,2}, {43,3}, {48,4}, {55,5}}, {5824}, nil, 2918, "顾问贝尔格拉姆", { xp = 5850, money = 13000, rep = { {47, 200, "铁炉堡"} } } },
        { 1956, nil, 35, nil, "塔贝萨", "尘泥沼泽 46,57", "驱除魔鬼", false, {1955}, nil, "找到一个黑曜石能量源，交给尘泥沼泽的塔贝萨。", "仅法师可做！能量源由黑曜石哨兵掉落。黑曜石哨兵就在后门里——从荒芜之地的后门（67,44）进去第一眼就能看到，没有小怪护卫。", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {8053}, "法师", 6546, "塔贝萨", nil },
        { 2240, "A", 35, 40, "巴尔洛戈", "奥达曼", "失踪的矮人", true, {2398}, {9626, 9627}, "读完巴尔洛戈的日记、探明密室，回铁炉堡向勘察员塔伯斯·雷矛汇报。", "密室在副本内。开门流程：从鲁维罗什拿索尔之杖，从巴尔洛戈的箱子拿尼基夫徽章，合成史前法杖；再到两间房之间的地图室召唤艾隆纳亚，击败后进入密室。", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, nil, nil, 6906, "巴尔洛戈", { xp = 3900, rep = { {47, 150, "铁炉堡"} } } },
        { 2398, nil, 35, nil, "勘察员塔伯斯·雷矛", "铁炉堡 - 探险者大厅 75,12", nil, false, nil, nil, "到奥达曼找到巴尔洛戈。", "巴尔洛戈在副本内。引导任务：若已接受或完成《隐藏的密室》，本任务将无法完成。", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, nil, nil, 1356, "勘察员塔伯斯·雷矛", nil },
        { 17, "A", 36, 42, "加克", "洛克莫丹 - 塞尔萨玛 37,49", "荒芜之地的材料", false, {2500}, {9030}, "采到 12 颗紫色蘑菇，带回塞尔萨玛交给加克。", "蘑菇（品红菌盖）散落在进本前的洞穴里（不在副本内），多在火堆旁和帐篷后面；学了草药学开追踪会在小地图上标出。每一步上交还给 250 点铁炉堡声望。前置任务同样在这名 NPC 处接。", {{38,2}, {40,3}, {45,4}, {52,5}}, {8047}, nil, 1470, "加克", { xp = 3450, money = 5500, rep = { {47, 100, "铁炉堡"} } } },
        { 2202, "H", 36, 42, "加卡尔", "荒芜之地 - 卡加斯 2,69", "荒芜之地的试剂", false, {2258}, {9030}, "收集 12 颗紫色蘑菇，交给卡加斯的加卡尔。", "前置同样在加卡尔处接。蘑菇散落副本各处；开草药追踪的小地图会直接标出。", {{36,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {8047}, nil, 6868, "加卡尔", { xp = 3450, money = 5500, rep = { {530, 100, "暗矛巨魔"} } } },
        { 2198, "A", 37, 41, "破碎的项链", "奥达曼内随机掉落", nil, false, nil, nil, "查清破碎项链的来历，评估它的价值。", "把项链带给铁炉堡的塔瓦斯德·基瑟尔（铁炉堡 - 秘法区 36,3）。", {{37,2}, {39,3}, {44,4}, {51,5}}, {7666}, nil, nil, nil, { xp = 3300 } },
        { 2199, "A", 37, 41, "塔瓦斯德·基瑟尔", "丹莫罗", nil, false, {2198}, nil, nil, nil, {{37,2}, {39,3}, {44,4}, {51,5}}, {2842}, nil, 6826, "塔瓦斯德·基瑟尔", { xp = 2450, rep = { {54, 75, "诺莫瑞根流亡者"} } } },
        { 2200, nil, 37, nil, "塔瓦斯德·基瑟尔", "铁炉堡 - 秘法区 36,3", "昂贵的知识", false, {2199}, nil, "到奥达曼寻找塔瓦斯的魔法项链——死去的圣骑士是最后一个持有者。", "那名圣骑士在副本内：遗体在守护者大厅（第一个「8」字形区域）的西北角，头顶黄问号、无需搜索互动。", {{37,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {7667}, nil, 6826, "塔瓦斯德·基瑟尔", nil },
        { 2204, "A", 37, 44, "塔瓦斯德的占卜之碗", "塔瓦斯德的占卜之碗", "寻找宝石", true, {2201}, nil, "从奥达曼最强的石人身上取得能量源，交给铁炉堡的塔瓦斯德。", "破碎项链的能量源由阿扎达斯掉落。", {{37,1}, {40,2}, {42,3}, {47,4}, {54,5}}, {7672}, nil, nil, nil, { xp = 930 } },
        { 2283, "H", 37, 41, "德兰·杜佛斯", "奥格瑞玛 - 暗巷区 59,36", nil, false, nil, nil, "在奥达曼挖掘场找一条珍贵的项链（可能已损坏），交给奥格瑞玛的德兰·杜佛斯。", "项链是副本内随机掉落。", {{37,2}, {39,3}, {44,4}, {51,5}}, {7666}, nil, 6986, "德兰·杜佛斯", { xp = 2450, rep = { {76, 75, "奥格瑞玛"} } } },
        { 2284, "H", 37, nil, "德兰·杜佛斯", "奥格瑞玛 - 暗巷区 59,36", "搜寻项链", false, {2283}, nil, "到奥达曼寻找与宝石有关的线索。", "那名圣骑士在副本内：进本后一直右手贴墙走就能到遗体处。", {{37,2}, {39,3}, {44,4}, {51,5}}, nil, nil, 6986, "德兰·杜佛斯", nil },
        { 2318, "H", 37, nil, "圣骑士的遗体", "奥达曼", "搜寻项链，再来一次", false, {2284}, nil, "在荒芜之地卡加斯哨所找一个能翻译圣骑士日记的人。", "人选是加卡尔（荒芜之地 - 卡加斯 2,46）；把项链借给他即可完成翻译。", {{37,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {7886}, nil, 6912, "圣骑士的遗体", nil },
        { 2338, "H", 37, 42, "加卡尔", "荒芜之地", "翻译日记", false, {2318}, nil, nil, nil, {{37,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {7886}, nil, 6868, "加卡尔", { xp = 345, rep = { {530, 10, "暗矛巨魔"} } } },
        { 2339, "H", 37, 44, "加卡尔", "荒芜之地 - 卡加斯 2,46", "翻译日记", false, {2338}, nil, "从奥达曼取回项链上的红宝石、黄宝石、蓝宝石和能量源，交给卡加斯的加卡尔。红宝石在暗铁矮人设防区，黄宝石在石腭怪区的一只瓮里，蓝宝石在石腭怪首领格瑞姆洛克手中，能量源在奥达曼最强的生物身上。", "宝石位置： 显眼的石罐、 暗影熔炉地窖、 格瑞姆洛克。开暗影熔炉地窖会刷怪，注意。", {{37,1}, {40,2}, {42,3}, {47,4}, {54,5}}, {7669, 7670, 7671, 7672, 7668}, nil, 6868, "加卡尔", { xp = 3750, rep = { {530, 100, "暗矛巨魔"} } } },
        { 2340, "H", 37, 44, "加卡尔", "荒芜之地", nil, false, nil, nil, nil, nil, {{37,1}, {40,2}, {42,3}, {47,4}, {54,5}}, {7887}, nil, 6868, "加卡尔", { xp = 1850, money = 12500, rep = { {76, 50, "奥格瑞玛"} } } },
        { 2361, "A", 37, 44, "塔瓦斯德·基瑟尔", "丹莫罗", nil, false, {2204}, {7673}, nil, nil, {{37,1}, {40,2}, {42,3}, {47,4}, {54,5}}, nil, nil, 6826, "塔瓦斯德·基瑟尔", { xp = 5600, rep = { {54, 200, "诺莫瑞根流亡者"} } } },
        { 2201, "A", 40, 43, "圣骑士的遗体", "奥达曼", "回到奥达曼", true, {2200}, nil, "在奥达曼查明红宝石、蓝宝石、黄宝石的下落，用塔瓦斯德给的占卜之瓶向他反馈。", "宝石分别在副本内的显眼石罐、暗影熔炉地窖，以及格瑞姆洛克身上。注意：打开暗影熔炉地窖会刷怪。", {{37,1}, {39,2}, {41,3}, {46,4}, {53,5}}, {7669, 7670, 7671, 7668}, nil, 6912, "圣骑士的遗体", { xp = 3600 } },
        { 2278, nil, 40, nil, "诺甘农圆盘", "奥达曼", nil, false, nil, nil, "向石头守护者了解古代知识，随后激活诺甘农圆盘；再把迷你版诺甘农圆盘带回铁炉堡探险者协会。", "接任务后先与石头守护者旁的圆盘对话，再用白金圆盘取得缩小版，交给资深探险家麦格拉斯（铁炉堡 - 探险者大厅 69,18）。后续任务在旁边 NPC 处接。", {{40,1}, {43,2}, {45,3}, {50,4}, {57,5}}, nil, nil, nil, nil, nil },
        { 2279, "A", 40, 47, "诺甘农圆盘", nil, "白金圆盘", true, nil, nil, nil, nil, {{40,1}, {43,2}, {45,3}, {50,4}, {57,5}}, {6064}, nil, nil, nil, { xp = 5250, rep = { {47, 150, "铁炉堡"} } } },
        { 2280, "H", 40, 47, "诺甘农圆盘", nil, "白金圆盘", true, {2278}, nil, nil, "杀掉阿扎达斯后进入其身后的宝库，点底座上的圆盘接任务；听召唤出的幽灵讲完全部故事后，再点一次圆盘拿到缩小版——漏了这步就得重跑一趟。回雷霆崖交任务（NPC 在 35,47 附近）。", {{40,1}, {43,2}, {45,3}, {50,4}, {57,5}}, {6064}, nil, nil, nil, { xp = 5250, rep = { {81, 150, "雷霆崖"} } } },
        { 2341, "H", 40, 44, "德兰·杜佛斯", "奥格瑞玛", nil, false, {2340}, {7888}, nil, nil, {{37,1}, {40,2}, {42,3}, {47,4}, {54,5}}, nil, nil, 6986, "德兰·杜佛斯", { xp = 5600, rep = { {530, 100, "暗矛巨魔"} } } },
