        { 7067, nil, 39, 48, "半人马贱民", "凄凉之地 45,86", nil, false, nil, {17774}, "阅读《贱民的指引》，从玛拉顿取回联合坠饰，交给凄凉之地南部的半人马贱民。", "《贱民的指引》里提到 5 个可汗。无名先知掉落灵魂护符，用它可以显现出 5 个可汗。", {{39,1}, {44,2}, {46,3}, {51,4}, {58,5}}, {17758, 17781}, nil, 13717, "半人马贱民", { xp = 5450, money = 14000 } },
