        { 7044, nil, 41, 49, "凯雯德拉", "凄凉之地 - 玛拉顿 副本入口地图", nil, false, nil, nil, "找回塞雷布拉斯节杖的两个部件——塞雷布拉斯魔棒和塞雷布拉斯钻石——然后设法与塞雷布拉斯对话。", "凯雯德拉就在进副本前的橙色区域起点。魔棒来自诺克塞恩，钻石来自维利塔恩。塞雷布拉斯在副本内，要先击败他才能对话。", {{41,1}, {45,2}, {47,3}, {52,4}, {59,5}}, {17703, 17702}, nil, 13697, "凯雯德拉", { xp = 3400 } },
        { 7046, nil, 41, 49, "赎罪的塞雷布拉斯", "玛拉顿", "玛拉顿的传说", true, {7044}, {17191}, "帮助赎罪的塞雷布拉斯制作塞雷布拉斯节杖，仪式完成后与他再谈一次。", "节杖由塞雷布拉斯亲手制作；仪式结束后与他对话即可。杖丢了可以再杀塞雷布拉斯，与他对话选「我丢了节杖」重新领取。", {{41,1}, {45,2}, {47,3}, {52,4}, {59,5}}, nil, nil, 13716, "赎罪的塞雷布拉斯", { xp = 5700 } },
