        { 7066, nil, 45, 51, "扎尔塔的灵魂", "玛拉顿", "大地的污染", true, {"大地的污染"}, nil, "到月光林地找到雷姆洛斯，把生命之种交给他。", "杀死公主后扎尔塔的灵魂会出现。雷姆洛斯在月光林地 - 雷姆洛斯神殿（36,41）。", {{39,1}, {47,2}, {49,3}, {54,4}, {62,5}}, {17760}, nil, 12238, "扎尔塔的灵魂", { xp = 6100, money = 15000, rep = { {609, 150, "塞纳里奥议会"} } } },
