        { 4241, nil, 75, nil, "科林的烈酒", "掉落自科林·烈酒", nil, false, {4224}, nil, "把科林的烈酒交给铁炉堡附近美酒节营地的埃菲库格·铁桶。", "仅美酒节期间可接，任务物品每角色限取一次。埃菲库格·铁桶在美酒节营地（丹莫罗 47,39）。", {{48,1}, {50,2}, {52,3}, {57,4}, {65,5}}, nil, nil, 9560, "麦克斯韦尔元帅", nil },
