        { 4862, nil, 55, 59, "基布雷尔", "燃烧平原 - 烈焰峰 65,22", nil, false, nil, {12529}, "到黑石塔替基布雷尔收集 15 枚尖塔蜘蛛卵。", "蜘蛛卵在副本内。拾卵时会随机刷出小蜘蛛，伤害高还带 AOE，留意。", {{55,2}, {57,3}, {62,4}, {71,5}}, {12530}, nil, 10260, "基布雷尔", { xp = 6400, money = 9000 } },
        { 4866, nil, 55, 60, "狼狈不堪的约翰", "燃烧平原 - 烈焰峰 65,23", nil, false, nil, {15873}, "在黑石塔中心找到烟网蛛后，与她战斗让她向你体内注入毒汁；有能力就顺手杀了她。中毒后回狼狈不堪的约翰那里，让他把「蛛后的乳汁」抽出来。", "烟网蛛后在副本内。注意：中途解毒会导致任务失败。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 9563, "狼狈不堪的约翰", { xp = 9950, money = 18000 } },
        { 4867, nil, 55, 60, "瓦罗什", "下层黑石塔", nil, true, nil, {15867}, "阅读瓦罗什的卷轴并把瓦罗什的蟑螂还给他。", "流程：先杀乌洛克拿头颅；长矛在副本内，用它召唤（召唤前会刷几群食人魔，可用长矛攻击）。◎ 每次刷新只限 1 人交任务——交了之后他就变回食人魔形态，不再有黄问号。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12712, 12730}, nil, 10799, "瓦罗什", { xp = 9950 } },
        { 4903, "H", 55, 60, "高图斯", "荒芜之地 - 卡加斯 65,22", nil, false, nil, {13958, 13959, 13961, 13962, 13963}, "击杀欧莫克大王、指挥官沃恩和维姆萨拉克，找到重要的黑石文件，向卡加斯的军官高图斯汇报。", "位置：欧莫克大王、指挥官沃恩、维姆萨拉克。黑石文件在其中一名 首领 旁边。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12562}, nil, nil, nil, { xp = 8300, money = 18000, rep = { {76, 150, "奥格瑞玛"} } } },
        { 4981, "H", 55, nil, "雷克斯洛特", "荒芜之地 - 卡加斯 5,47", nil, false, nil, nil, "到黑石塔查明比修的下落。", "比修在副本内。", {{55,2}, {57,3}, {62,4}, {71,5}}, nil, nil, 9080, "雷克斯洛特", nil },
        { 4982, "H", 55, 59, "比修", "下层黑石塔", "狡猾的比修", true, {4981}, nil, "找回比修的装置还给她——她记得藏在城市最底层。", "装置在通往烟网蛛后的路上。", {{55,2}, {57,3}, {62,4}, {71,5}}, {12345}, nil, 10257, "比修", { xp = 6400 } },
        { 4983, "H", 55, 59, "比修", nil, nil, true, {4982}, {15858, 15859}, nil, nil, {{55,2}, {57,3}, {62,4}, {71,5}}, {12652}, nil, 10257, "比修", { xp = 6400, money = 18000, rep = { {76, 100, "奥格瑞玛"} } } },
        { 5001, "A", 55, 59, "比修", "下层黑石塔", nil, true, nil, nil, "找回比修的装置还给她。祝你好运！", "装置在通往烟网蛛后的路上。后续找麦克斯韦元帅（燃烧平原 - 摩根的岗哨 84,58）。", {{55,2}, {57,3}, {62,4}, {71,5}}, {12345}, nil, 10257, "比修", { xp = 6400 } },
        { 5002, "A", 55, 59, "比修", nil, nil, true, {5001}, nil, nil, nil, {{55,2}, {57,3}, {62,4}, {71,5}}, {12770}, nil, 10257, "比修", { xp = 6400, money = 18000, rep = { {72, 100, "暴风城"} } } },
        { 5047, nil, 55, 60, "芬克·恩霍尔", "上层黑石塔", nil, true, nil, nil, "与永望镇的玛雷弗斯·暗锤谈一谈。", "剥完比斯巨兽的皮后芬克·恩霍尔才会出现。玛雷弗斯·暗锤在冬泉谷 - 永望镇（61,38）。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12710}, nil, 10776, "皮普·急智", { xp = 6600 } },
        { 5081, "A", 55, 60, "麦克斯韦尔", "燃烧平原 - 摩根的岗哨 84,58", "给麦克斯韦尔的消息", false, {5002}, {13958, 13959, 13961, 13962, 13963}, "到黑石塔消灭指挥官沃恩、欧莫克大王和维姆萨拉克，回麦克斯韦尔元帅处复命。", "位置：沃恩、欧莫克大王、维姆萨拉克。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 9560, "麦克斯韦尔元帅", { xp = 8300, money = 18000, rep = { {72, 150, "暴风城"} } } },
        { 5089, "A", 55, 60, nil, "达基萨斯将军的命令掉落自（维姆萨拉克）", nil, false, nil, nil, "把达基萨斯将军的命令交给燃烧平原的麦克斯韦尔元帅。", "麦克斯韦尔元帅在燃烧平原 - 摩根的岗哨（84,58）。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12780}, nil, nil, nil, { xp = 6600, rep = { {72, 100, "暴风城"} } } },
        { 5127, nil, 55, 60, "罗拉克斯", "冬泉谷 64,74", "罗拉克斯的故事", false, {5126}, {12696, 9224, 12849}, "到黑石塔找到古拉鲁克，杀死后用血污长矛刺入尸体吸干灵魂炼成穿魂长矛；再找一块未铸造的符文覆饰胸甲，把两样都交给冬泉谷的罗拉克斯。", "锻造任务。古拉鲁克在副本内。需要锻造 270 才能接。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12847, 12806, 12848}, nil, 10918, "罗拉克斯", { xp = 8300 } },
        { 6569, "H", 55, 60, "巫女麦兰达", "西瘟疫之地 50,77", "幻术的欺诈", false, {6568}, nil, "到黑石塔收集 20 颗黑色龙人的眼球，回巫女麦兰达处复命。", "黑龙系的敌人都会掉眼球。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16786}, nil, 11872, "巫女麦兰达", { xp = 6600 } },
        { 5103, nil, 56, nil, "人类的残骸", "下层黑石塔", nil, false, nil, nil, "世界上一定有人知道这副手套的来历。祝你好运！", "锻造任务。从人类残骸附近拿到板甲手套，交给玛雷弗斯·暗锤（冬泉谷 - 永望镇 61,39）。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, nil, nil, nil },
        { 4734, nil, 57, 60, "丁奇·斯迪波尔", "燃烧平原 - 烈焰峰 65,24", "丁奇·斯迪波尔", false, {4907}, {12144}, "在孵化间对一颗龙蛋使用龙蛋冷冻器初号机。", "龙蛋在烈焰之父的房间。冻蛋后别去点蛋，直接用背包里的装置；打完达基萨斯将军后可以直接跳下龙蛋房单独补做。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12286}, nil, 10267, "丁奇·斯迪波尔", { xp = 8300, money = 18000, rep = { {169, 150, "热砂港"} } } },
        { 4735, nil, 57, 60, "丁奇·斯迪波尔", "燃烧平原 - 烈焰峰 65,24", "冷冻龙蛋", false, {4734}, nil, "把电动采集模块和 8 颗龙蛋交给燃烧平原烈焰峰的丁奇·斯迪波尔。", "龙蛋都在烈焰之父的房间里。冻住蛋后靠近使用背包里的装置即可（不用点蛋）；团里没人管的话，打完将军跳下龙蛋房可单独补做。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12241, 12287}, nil, 10267, "丁奇·斯迪波尔", { xp = 9950, money = 27000, rep = { {169, 200, "热砂港"} } } },
        { 4742, nil, 57, 60, "维埃兰", "下层黑石塔", nil, true, nil, nil, "找齐三块命令宝石——燃棘宝钻、尖石宝钻、血斧宝钻——连同原始晋升印章一起交给维埃兰。", "宝石来源：欧莫克大王、指挥官沃恩、维姆萨拉克。原始晋升印章由黑石塔小怪掉落。完成后即可拿到上层黑石塔的钥匙。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12336, 12335, 12337, 12219}, nil, 10299, "裂盾渗透者", { xp = 8300 } },
        { 4743, nil, 57, 60, "裂盾渗透者", nil, nil, true, {4742}, {12344}, nil, "在龙下方的水中使用未铸造的印章开启铸印事件。事件一次只出 1 枚可拾取的锻造印章，且龙有 3 小时冷却——一晚只能做一个人。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12324, 12339}, nil, 10299, "裂盾渗透者", { xp = 9950 } },
        { 4764, "A", 57, 60, "玛亚拉·布莱特文", "燃烧平原 - 摩根的岗哨 84,69", "玛亚拉·布莱特文", false, {4766}, nil, "把末日扣环交给燃烧平原的玛亚拉·布莱特文。", "前置可从雷明顿·瑞治维尔伯爵接（暴风城 - 暴风要塞 77,47）。扣环在烈焰之父房间的箱子里。箱子约 20 秒刷新一次，多人可轮流开。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12352}, nil, 9565, "玛亚拉·布莱特文", { xp = 1650, rep = { {72, 25, "暴风城"} } } },
        { 4765, "A", 57, 60, "玛亚拉·布莱特文", "燃烧平原", nil, false, {4764}, {15861, 15860}, nil, nil, {{57,2}, {58,3}, {63,4}, {72,5}}, {12437}, nil, 9565, "玛亚拉·布莱特文", { xp = 6600, money = 27000, rep = { {72, 100, "暴风城"} } } },
        { 5160, nil, 57, 60, "奥比", "上层黑石塔", nil, true, nil, nil, "到冬泉谷找到哈尔琳，把奥比的鳞片交给她。", "奥比在竞技场旁的房间，蹲在一处凸台上。哈尔琳在冬泉谷（54,51）；从洞穴最里面的传送符文站上去就能到她身边。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12923}, nil, 10740, "奥比", { xp = 6600 } },
        { 8966, nil, 58, 60, "伯德雷", "黑石山 副本入口地图[D]", "重要的材料", false, {8962}, nil, "用召唤火盆召出莫尔·灰蹄的灵魂并杀掉他，把火盆和瓦塔拉克饰品左瓣带回黑石山交给伯德雷。", "需要超维度幽灵显形器才能看到伯德雷（从《寻找安泰恩》获得）。莫尔·灰蹄在副本内召唤。", {{58,3}, {63,4}, {72,5}}, {21984, 22049}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 8989, nil, 58, 60, "伯德雷", "黑石山 副本入口地图[D]", "更多重要的材料", false, {8986}, nil, "在比斯巨兽的房间用召唤火盆召出瓦塔拉克公爵，杀死后对尸体使用瓦塔拉克的饰品，再把饰品还给瓦塔拉克公爵之魂。", "需要超维度幽灵显形器才能看到伯德雷（从《寻找安泰恩》获得）。莫尔·灰蹄在副本内召唤。", {{58,3}, {63,4}, {72,5}}, {22048, 22049}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 8995, nil, 58, 60, "伯德雷", "黑石山 副本入口地图[D]", "最后的准备", false, {8994}, nil, "在比斯巨兽的房间用召唤火盆召出瓦塔拉克公爵，杀死后对尸体使用瓦塔拉克的饰品，再把饰品还给瓦塔拉克公爵之魂。", "需要超维度幽灵显形器才能看到伯德雷（从《寻找安泰恩》获得）。瓦塔拉克公爵在副本内召唤；奖励向伯德雷领取。", {{58,3}, {63,4}, {72,5}}, {22048, 22056}, nil, 16033, "伯德雷", { xp = 9950 } },
    },
