        { 1318, nil, 56, 60, nil, nil, nil, false, nil, {18366, 18367, 18368, 18369}, nil, "可一趟连做，推荐路线：先北（贡品，备好食人魔套装材料与坏陷阱）→ 西（杀伊莫塔尔）→ 图书馆（杀托塞德林王子）→ 回北出门时向芬古斯交任务。", {{56,2}, {58,3}, {63,4}, {72,5}}, {18336}, nil, nil, nil, { xp = 8300 } },
        { 5518, nil, 56, 60, "诺特·希姆加克", "厄运之槌 北，", nil, true, nil, {18258}, "把 4 卷符文布、8 块硬甲皮、2 卷符文线和一份食人魔鞣酸交给被拴在厄运之槌戈多克食人魔区的诺特·希姆加克。", "可重复任务。食人魔鞣酸在副本上层附近获取。", {{56,2}, {58,3}, {63,4}, {72,5}}, {14048, 8170, 14341, 18240}, nil, 14338, "诺特·希姆加克", { xp = 6600, rep = { {169, 100, "热砂港"} } } },
