        { 7481, "H", 54, nil, "先知科鲁拉克", "菲拉斯 - 莫沙彻营地 74,43", nil, false, nil, nil, "到厄运之槌找到卡里尔·温萨鲁斯，向莫沙彻营地的先知科鲁拉克报告你查到的东西。", "卡里尔·温萨鲁斯在厄运之槌西区的图书馆。骸骨在图书馆中央、博学者莱德罗斯旁边。", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14373, "先知科鲁拉克", nil },
