    ["scholomance"] = {
        { 5341, "H", 52, 60, "阿莱克斯·巴罗夫", "提瑞斯法林地 - 亡灵壁垒 80,73", nil, false, nil, nil, "到通灵学院取回巴罗夫家族的四份地契（凯尔达隆、布瑞尔、塔伦米尔、南海镇），交回阿莱克斯·巴罗夫。", "地契位置：凯尔达隆在进门后的第一间大厅；南海镇=过桥后第一间大厅左角书桌上；塔伦米尔=幼龙房前房间的右角书桌；布瑞尔=莱斯·霜语所在的房间。", {{52,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13471, 13448, 13450, 13451}, nil, 11022, "阿莱克斯·巴罗夫", { xp = 6600, money = 18000 } },
        { 5343, "A", 52, 60, "维尔顿·巴罗夫", "西瘟疫之地 - 寒风营地 43,83", nil, false, nil, nil, "到通灵学院取回巴罗夫家族的四份地契（凯尔达隆、布瑞尔、塔伦米尔、南海镇），交回维尔顿·巴罗夫。", "地契位置：凯尔达隆在进门后的第一间大厅；南海镇=过桥后第一间大厅左角书桌上；塔伦米尔=幼龙房前房间的右角书桌；布瑞尔=莱斯·霜语所在的房间。", {{52,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13471, 13448, 13450, 13451}, nil, 11023, "维尔顿·巴罗夫", { xp = 6600, money = 18000 } },
        { 5382, nil, 55, 60, "艾瓦·萨克霍夫", "西瘟疫之地 - 凯尔达隆 70,73", nil, false, nil, nil, "在通灵学院找到瑟尔林·卡斯迪诺夫教授，杀掉他并烧毁艾瓦·萨克霍夫与卢森·萨克霍夫的遗体，然后回艾瓦·萨克霍夫处复命。", "教授死后看房间两侧的肉堆——伊娃·萨克霍夫夫妇的遗骸就在里面，清掉即完成。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 11216, "艾瓦·萨克霍夫", { xp = 6600 } },
        { 5384, nil, 55, 60, "艾瓦·萨克霍夫", "西瘟疫之地 - 凯尔达隆 70,73", "卡斯迪诺夫的恐惧之袋", false, {5515}, {15805, 15806, 13544}, "带无辜者之血回通灵学院，倒在门廊火盆下引出基尔图诺斯；勇敢迎战，别退缩。杀死他后回艾瓦·萨克霍夫处复命。", "门廊在副本内。无辜者之血在第一间房的魅魔身上 100% 掉落；若召唤的克尔托诺斯没开出想要的奖励，可放弃重接（需重置副本重新召唤）。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13523}, nil, 11216, "艾瓦·萨克霍夫", { xp = 8300 } },
        { 5515, nil, 55, 60, "艾瓦·萨克霍夫", "西瘟疫之地 - 凯尔达隆 70,73", "瑟尔林·卡斯迪诺夫教授", false, {5382}, nil, "在通灵学院击败詹迪斯·巴罗夫，从尸体上取得卡斯迪诺夫的恐惧之袋，交给艾瓦·萨克霍夫。", "詹迪斯·巴罗夫在副本内。分身只有本体有血条——开血条显示（V 键）或给本体上标记，只打有血条的那个。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13725}, nil, 11216, "艾瓦·萨克霍夫", { xp = 6600 } },
        { 5529, nil, 55, 58, "贝蒂娜·比格辛克", "东瘟疫之地 - 圣光之愿礼拜堂 76,54", nil, false, nil, nil, "击杀 20 只瘟疫龙崽，回圣光之愿礼拜堂向贝蒂娜·比格辛克复命。", "瘟疫龙崽在尸骨储藏所——去往血骨傀儡的大房间那片。", {{55,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 11035, "贝蒂娜·比格辛克", { xp = 6200, money = 9000, rep = { {529, 100, "银色黎明"} } } },
        { 5582, nil, 55, nil, "健康的龙鳞", "通灵学院瘟疫龙崽随机掉落", "瘟疫之龙", false, {5529}, nil, "把健康的龙鳞交给东瘟疫之地圣光之愿礼拜堂的贝蒂娜·比格辛克。", "要先完成《瘟疫龙崽》才会出现可采的健康龙鳞（否则看不见）。健康的龙鳞由瘟疫龙崽掉落（约 8%）。贝蒂娜·比格辛克在东瘟疫之地 - 圣光之愿礼拜堂（76,54）。", {{55,2}, {56,3}, {61,4}, {69,5}}, {13920}, nil, nil, nil, nil },
        { 4771, nil, 57, 60, "贝蒂娜·比格辛克", "东瘟疫之地 - 圣光之愿礼拜堂 77,54", "贝蒂娜·比格辛克", false, {5531}, {15853, 15854}, "把黎明先锋放到通灵学院的观察室，击败维克图斯后回贝蒂娜·比格辛克处复命。", "前置「雏龙精华」始于丁奇·斯迪波尔（燃烧平原 - 烈焰峰 65,23）。观察室在副本内。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12368}, nil, 11035, "贝蒂娜·比格辛克", { xp = 9950, money = 27000, rep = { {529, 200, "银色黎明"} } } },
        { 5466, nil, 57, 60, "马杜克镇长", "西瘟疫之地 - 凯尔达隆 70,73", "禁锢灵魂的遗物", false, {5465}, {13982, 13986, 13984, 14002}, "在通灵学院找到莱斯·霜语，用禁锢灵魂的遗物破除他的亡灵外壳，成功后杀掉他，把头颅交给马杜克镇长。", "莱斯·霜语在副本内。", {{57,2}, {58,3}, {63,4}, {72,5}}, {13626, 13752}, nil, 11286, "马杜克镇长", { xp = 9950 } },
        { 5531, nil, 57, 60, "莱尼德·巴萨罗梅", "东瘟疫之地", "莱尼德·巴萨罗梅", false, {5522}, nil, nil, nil, {{57,2}, {58,3}, {63,4}, {72,5}}, {13761}, nil, 11036, "莱尼德·巴萨罗梅", { xp = 1650, rep = { {529, 25, "银色黎明"} } } },
        { 8258, "H", 58, nil, "萨格尼", "奥格瑞玛 - 智慧谷 38.6, 36.2", "收集材料", false, {7667}, nil, "在通灵学院地下室的尸骨储藏所中心使用预言水晶球，击败召唤出的幽灵；死亡骑士达克雷尔现身后再击败他，把头颅交给奥格瑞玛智慧谷的萨格尼。", "萨满祭司专属任务，前置接自同一 NPC。达克雷尔在副本内召唤。", {{58,3}, {63,4}, {72,5}}, {18880, 18746}, "萨满", nil, nil, nil },
        { 8969, nil, 58, 60, "伯德雷", "黑石山 副本入口地图[D]", "重要的材料", false, {8965}, nil, "用召唤火盆召出库尔莫克的灵魂并杀掉他，把火盆和瓦塔拉克饰品左瓣还给黑石山的伯德雷。", "需要超维度幽灵显形器才能看到伯德雷（从《寻找安泰恩》获得）。库尔莫克在副本内。", {{58,3}, {63,4}, {72,5}}, {21984, 22052}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 8992, nil, 58, 60, "伯德雷", "黑石山 副本入口地图[D]", "更多重要的材料", false, {8988}, nil, "用召唤火盆召出库尔莫克的灵魂并杀掉他，把火盆和瓦塔拉克公爵的饰品还给黑石山的伯德雷。", "需要超维度幽灵显形器才能看到伯德雷（从《寻找安泰恩》获得）。库尔莫克在副本内。", {{58,3}, {63,4}, {72,5}}, {22048, 22052}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 7629, nil, 60, nil, "戈瑟奇·邪眼", "燃烧平原 12,31", "克索诺斯星尘", false, {7625}, nil, "把瓶中的小鬼带到通灵学院的炼金实验室，等它造出羊皮纸后把瓶子还给戈瑟奇·邪眼。", "仅术士可接！炼金实验室就在莱斯·霜语所在的房间里。", {{60,3}, {4,4}, {6,5}}, {18688}, "术士", 14437, "戈瑟奇·邪眼", nil },
        { 7647, nil, nil, nil, nil, nil, nil, false, {7646}, nil, nil, nil, {{60,3}, {4,4}, {6,5}}, {18799, 18792, 18804}, "圣骑士", 928, "格雷森·沙东布瑞克公爵", nil },
