    ["stratholme_main"] = {
        { 5305, nil, 50, nil, "轻盈的莉莉丝", "冬泉谷 - 永望镇 61,37", nil, false, nil, nil, "到斯坦索姆杀死红衣铸锤师，把他的围裙交给莉莉丝。", "红衣铸锤师靠召唤出现：点击地上的「锻造计划书」羊皮纸触发。", {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13351}, nil, 11191, "轻盈的莉莉丝", nil },
        { 5307, nil, 50, nil, "亡灵杀手瑟里尔", "冬泉谷 - 永望镇 61,37", nil, false, nil, nil, "在斯坦索姆找到黑衣守卫铸剑师并杀掉，把黑色卫士徽记交给亡灵杀手瑟里尔。", "黑衣守卫铸剑师靠召唤出现：点击安娜丝塔丽之塔旁当铺边地上的「锻造计划书」触发。", {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13350}, nil, 11193, "亡灵杀手瑟里尔", nil },
        { 5848, nil, 52, 60, "画家瑞弗蕾", "西瘟疫之地 - 凯尔达隆 65,75", "爱与家庭", false, {5846}, nil, "到斯坦索姆的血色十字军堡垒找回名画「爱与家庭」——它藏在另一幅双月之画的后面——把画归还给提里奥·弗丁。", "前置从提里奥·弗丁处接（西瘟疫之地 7,43）。画在活人区档案室进门右手边。", {{52,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {14679}, nil, 11936, "画家瑞弗蕾", { xp = 6600 } },
        { 5125, nil, 55, 60, "奥里克斯", "斯坦索姆", "信仰奖章", true, {"信仰奖章"}, {17044, 17045}, "击杀瑞文戴尔男爵。", "先给奥里克斯 [信仰奖章]（奖章在副本内的玛洛尔保险箱里）；他会加入对抗男爵的战斗但会倒下。杀死男爵后与尸体对话完成任务。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10917, "奥里克斯", { xp = 9950 } },
        { 5212, nil, 55, nil, "贝蒂娜·比格辛克", "东瘟疫之地 - 圣光之愿礼拜堂 76,54", nil, false, nil, nil, "从斯坦索姆找回 20 个瘟疫肉块，交给贝蒂娜·比格辛克。", "斯坦索姆大部分敌人都会掉肉块，但掉率偏低。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13174}, nil, 11035, "贝蒂娜·比格辛克", { xp = 6600, money = 18000, rep = { {529, 100, "银色黎明"} } } },
        { 5213, nil, 55, 60, "贝蒂娜·比格辛克", "东瘟疫之地 - 圣光之愿礼拜堂 76,54", "血肉不会撒谎", false, {5212}, {13209, 19812}, "到斯坦索姆探索通灵塔，找到新的天灾军团档案交给贝蒂娜·比格辛克。", "档案小盒随机刷在奈鲁布恩坎、安娜丝塔丽、马勒基三座通灵塔中的一座里；盒子不会消失，全队每人都拿得到。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13176}, nil, 11035, "贝蒂娜·比格辛克", { xp = 6600, rep = { {529, 100, "银色黎明"} } } },
        { 5214, nil, 55, 60, "烟鬼拉鲁恩", "东瘟疫之地 - 圣光之愿礼拜堂 75,52", nil, false, nil, {13171}, "在斯坦索姆找到弗拉斯·希亚比的烟草店，取回一盒希亚比的烟草交给烟鬼拉鲁恩。", "烟草店在副本内：一路左转到底的死角、水井右侧，需清完沿途；开盒的瞬间弗拉斯·希亚比会现身。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13172}, nil, 11033, "烟鬼拉鲁恩", { xp = 8300 } },
        { 5243, nil, 55, 60, "莱尼德·巴萨罗梅", "东瘟疫之地 - 圣光之愿礼拜堂 76,52", nil, false, nil, {13216, 13217, 3928, 6149}, "前往斯坦索姆，搜刮城中散落的补给箱，收集 5 瓶斯坦索姆圣水，回莱尼德·巴萨罗梅处复命。", "圣水在城中各处的箱子里；部分是假箱，打开会钻出一堆虫子。矮人用「寻宝」能在小地图上标出真箱子。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13180}, nil, 11036, "莱尼德·巴萨罗梅", { xp = 6600, money = 18000, rep = { {529, 100, "银色黎明"} } } },
        { 5251, nil, 55, 60, "尼古拉斯·瑟伦霍夫公爵", "东瘟疫之地 - 圣光之愿礼拜堂 76,52", nil, false, nil, nil, "在斯坦索姆找到血色十字军的档案管理员加尔福特，杀掉并烧毁血色十字军档案。", "档案与档案管理员都在副本内。◎ 若同时在做《爱与家庭》：烧档案前先拿到画——画和档案会被一起烧掉。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 11039, "尼古拉斯·瑟伦霍夫公爵", { xp = 8300, money = 18000, rep = { {529, 150, "银色黎明"} } } },
        { 5262, nil, 55, 60, "巴纳扎尔", "斯坦索姆", "档案管理员", false, nil, nil, "把巴纳扎尔的头颅交给东瘟疫之地的尼古拉斯·瑟伦霍夫公爵。", "公爵在东瘟疫之地 - 圣光之愿礼拜堂（76,52）。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13250}, nil, nil, nil, { xp = 8300, rep = { {529, 150, "银色黎明"} } } },
        { 5263, nil, 55, nil, "尼古拉斯·瑟伦霍夫公爵", "东瘟疫之地 - 圣光之愿礼拜堂 76,52", "可怕的真相", false, {5262}, nil, "到斯坦索姆击杀瑞文戴尔男爵，把头颅交给尼古拉斯·瑟伦霍夫公爵。", "男爵在副本内。此任务有后续任务给奖励。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13251}, nil, 11039, "尼古拉斯·瑟伦霍夫公爵", { xp = 8300, rep = { {529, 150, "银色黎明"} } } },
        { 5282, nil, 55, 60, "埃根", "东瘟疫之地 11,29", "永不安息的灵魂", false, {5281}, {13315}, "对斯坦索姆的鬼魂居民使用埃根的冲击器；灵魂脱离躯壳后再用一次，让它们彻底安息。解放 15 个永不安息的灵魂后回埃根处复命。", "前置从护理者奥林处接（东瘟疫之地 - 圣光之愿礼拜堂 74,58）。鬼魂居民在城中到处游荡。冲击枪打中鬼魂约 10 秒后其身边会出现「不安的灵魂」，对它再补一枪即可拾取。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13289}, nil, 11140, "埃根", { xp = 8300, money = 18000 } },
        { 6163, "H", 56, nil, "纳萨诺斯·凋零者", "东瘟疫之地 22,68", "暗翼蝠", false, {6135}, nil, "到斯坦索姆击杀吞咽者拉姆斯登，把头颅交给纳萨诺斯。", "前置同样在纳萨诺斯处接。拉姆斯登在副本内。", {{56,2}, {58,3}, {63,4}, {72,5}}, {15880}, nil, 11878, "纳萨诺斯·凋零者", { xp = 6600, money = 18000, rep = { {68, 100, "幽暗城"} } } },
        { 5463, nil, 57, 60, "莱尼德·巴萨罗梅", "东瘟疫之地 - 圣光之愿礼拜堂 75,52", "亡灵莱斯·霜语", false, {5462}, nil, "到斯坦索姆找到米奈希尔的礼物，把巫妖生前的遗物放在那块邪恶的土地上。", "前置从马杜克镇长处接（西瘟疫之地 - 凯尔达隆 70,73）。标记就是男爵房间地上的五芒星。另见通灵学院的「巫妖莱斯·霜语」。", {{57,2}, {58,3}, {63,4}, {72,5}}, {13585}, nil, 11036, "莱尼德·巴萨罗梅", { xp = 6600 } },
        { 8945, nil, 58, 60, "伊思达·哈尔蒙", "东瘟疫之地 - 斯坦索姆", "寻找安泰恩", false, {8929}, {22137}, "进入斯坦索姆，从瑞文戴尔男爵手中救出伊思达。", "伊思达·哈尔蒙就站在副本门口，需要超维度幽灵显形器才能看到他。前置：联盟找德莉亚娜（铁炉堡 43,52），部落找莫克瓦尔（奥格瑞玛 38,37）。这也是著名的「45 分钟瑞文戴尔」任务。", {{58,3}, {63,4}, {72,5}}, nil, nil, 16016, "安泰恩·哈尔蒙", { xp = 8300 } },
        { 8968, nil, 58, 60, "伯德雷", "黑石山 副本入口地图中的[D]", "重要的材料", false, {8964}, nil, "用召唤火盆召出亚雷恩和索托斯的灵魂并杀掉他们，把火盆和瓦塔拉克饰品左瓣还给黑石山的伯德雷。", "需要超维度幽灵显形器才能看到伯德雷（从《寻找安泰恩》获得）。两人在副本内召唤。", {{58,3}, {63,4}, {72,5}}, {21984, 22051}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 8991, nil, 58, 60, "伯德雷", "黑石山 副本入口地图中的[D]", "更多重要的材料", false, {8987}, nil, "用召唤火盆召出亚雷恩和索托斯的灵魂并杀掉他们，把火盆和瓦塔拉克公爵的饰品还给黑石山的伯德雷。", "需要超维度幽灵显形器才能看到伯德雷（从《寻找安泰恩》获得）。两人在副本内召唤。", {{58,3}, {63,4}, {72,5}}, {22048, 22051}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 7622, nil, 60, nil, "艾瑞斯·哈文法", "东瘟疫之地 17,14", "警示", false, {7621}, nil, "在 15 个农夫被杀之前拯救 50 个农夫，完成后与艾瑞斯·哈文法谈谈。拯救进度可以看死亡布告。", "见到艾瑞斯·哈文法并接任务需要神圣之眼（火焰之王的宝箱，熔火之心出）。完成后把神圣之眼、诺达希尔碎片和暗影之眼（诅咒之地/冬泉谷随机恶魔掉落）组合，得到牧师史诗法杖——祈福。", {{60,3}, {63,4}, {72,5}}, nil, "牧师", 14494, "艾瑞斯·哈文法", nil },
        { 9257, nil, 60, nil, "阿纳克洛斯", "塔纳利斯 - 时光之穴 65,49", "埃提耶什，被玷污的传说之杖", false, {9251}, nil, "塔纳利斯时光之穴的阿纳克洛斯要你前往斯坦索姆，在神圣之地上使用埃提耶什、守护者的传说之杖，击败被驱赶出来的生物后回他那里复命。", "召唤位置在副本内。巫妖王之怒资料片中无法再获得此任务；只有「召唤出埃提耶什」这一步仍可完成。", {{60,3}, {63,4}, {72,5}}, {22737}, "牧师", nil, nil, nil },
    },
    ["stratholme_service"] = {
        { 5305, nil, 50, nil, "轻盈的莉莉丝", "冬泉谷 - 永望镇 61,37", nil, false, nil, nil, "到斯坦索姆杀死红衣铸锤师，把他的围裙交给莉莉丝。", "红衣铸锤师靠召唤出现：点击地上的「锻造计划书」羊皮纸触发。", {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13351}, nil, 11191, "轻盈的莉莉丝", nil },
        { 5307, nil, 50, nil, "亡灵杀手瑟里尔", "冬泉谷 - 永望镇 61,37", nil, false, nil, nil, "在斯坦索姆找到黑衣守卫铸剑师并杀掉，把黑色卫士徽记交给亡灵杀手瑟里尔。", "黑衣守卫铸剑师靠召唤出现：点击安娜丝塔丽之塔旁当铺边地上的「锻造计划书」触发。", {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13350}, nil, 11193, "亡灵杀手瑟里尔", nil },
        { 5848, nil, 52, 60, "画家瑞弗蕾", "西瘟疫之地 - 凯尔达隆 65,75", "爱与家庭", false, {5846}, nil, "到斯坦索姆的血色十字军堡垒找回名画「爱与家庭」——它藏在另一幅双月之画的后面——把画归还给提里奥·弗丁。", "前置从提里奥·弗丁处接（西瘟疫之地 7,43）。画在活人区档案室进门右手边。", {{52,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {14679}, nil, 11936, "画家瑞弗蕾", { xp = 6600 } },
        { 5125, nil, 55, 60, "奥里克斯", "斯坦索姆", "信仰奖章", true, {"信仰奖章"}, {17044, 17045}, "击杀瑞文戴尔男爵。", "先给奥里克斯 [信仰奖章]（奖章在副本内的玛洛尔保险箱里）；他会加入对抗男爵的战斗但会倒下。杀死男爵后与尸体对话完成任务。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10917, "奥里克斯", { xp = 9950 } },
        { 5212, nil, 55, 60, "贝蒂娜·比格辛克", "东瘟疫之地 - 圣光之愿礼拜堂 76,54", nil, false, nil, nil, "从斯坦索姆找回 20 个瘟疫肉块，交给贝蒂娜·比格辛克。", "斯坦索姆大部分敌人都会掉肉块，但掉率偏低。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13174}, nil, 11035, "贝蒂娜·比格辛克", { xp = 6600, money = 18000, rep = { {529, 100, "银色黎明"} } } },
        { 5213, nil, 55, 60, "贝蒂娜·比格辛克", "东瘟疫之地 - 圣光之愿礼拜堂 76,54", "血肉不会撒谎", false, {5212}, {13209, 19812}, "到斯坦索姆探索通灵塔，找到新的天灾军团档案交给贝蒂娜·比格辛克。", "档案小盒随机刷在奈鲁布恩坎、安娜丝塔丽、马勒基三座通灵塔中的一座里；盒子不会消失，全队每人都拿得到。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13176}, nil, 11035, "贝蒂娜·比格辛克", { xp = 6600, rep = { {529, 100, "银色黎明"} } } },
        { 5214, nil, 55, 60, "烟鬼拉鲁恩", "东瘟疫之地 - 圣光之愿礼拜堂 75,52", nil, false, nil, {13171}, "在斯坦索姆找到弗拉斯·希亚比的烟草店，取回一盒希亚比的烟草交给烟鬼拉鲁恩。", "烟草店在副本内：一路左转到底的死角、水井右侧，需清完沿途；开盒的瞬间弗拉斯·希亚比会现身。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13172}, nil, 11033, "烟鬼拉鲁恩", { xp = 8300 } },
        { 5243, nil, 55, 60, "莱尼德·巴萨罗梅", "东瘟疫之地 - 圣光之愿礼拜堂 76,52", nil, false, nil, {13216, 13217, 3928, 6149}, "前往斯坦索姆，搜刮城中散落的补给箱，收集 5 瓶斯坦索姆圣水，回莱尼德·巴萨罗梅处复命。", "圣水在城中各处的箱子里；部分是假箱，打开会钻出一堆虫子。矮人用「寻宝」能在小地图上标出真箱子。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13180}, nil, 11036, "莱尼德·巴萨罗梅", { xp = 6600, money = 18000, rep = { {529, 100, "银色黎明"} } } },
        { 5251, nil, 55, nil, "尼古拉斯·瑟伦霍夫公爵", "东瘟疫之地 - 圣光之愿礼拜堂 76,52", nil, false, nil, nil, "在斯坦索姆找到血色十字军的档案管理员加尔福特，杀掉并烧毁血色十字军档案。", "档案与档案管理员都在副本内。◎ 若同时在做《爱与家庭》：烧档案前先拿到画——画和档案会被一起烧掉。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 11039, "尼古拉斯·瑟伦霍夫公爵", { xp = 8300, money = 18000, rep = { {529, 150, "银色黎明"} } } },
        { 5262, nil, 55, nil, "巴纳扎尔", "斯坦索姆", "档案管理员", false, nil, nil, "把巴纳扎尔的头颅交给东瘟疫之地的尼古拉斯·瑟伦霍夫公爵。", "公爵在东瘟疫之地 - 圣光之愿礼拜堂（76,52）。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13250}, nil, nil, nil, { xp = 8300, rep = { {529, 150, "银色黎明"} } } },
        { 5263, nil, 55, 60, "尼古拉斯·瑟伦霍夫公爵", "东瘟疫之地 - 圣光之愿礼拜堂 76,52", "可怕的真相", false, {5262}, nil, "到斯坦索姆击杀瑞文戴尔男爵，把头颅交给尼古拉斯·瑟伦霍夫公爵。", "男爵在副本内。此任务有后续任务给奖励。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13251}, nil, 11039, "尼古拉斯·瑟伦霍夫公爵", { xp = 8300, rep = { {529, 150, "银色黎明"} } } },
        { 5282, nil, 55, 60, "埃根", "东瘟疫之地 11,29", "永不安息的灵魂", false, {5281}, {13315}, "对斯坦索姆的鬼魂居民使用埃根的冲击器；灵魂脱离躯壳后再用一次，让它们彻底安息。解放 15 个永不安息的灵魂后回埃根处复命。", "前置从护理者奥林处接（东瘟疫之地 - 圣光之愿礼拜堂 74,58）。鬼魂居民在城中到处游荡。冲击枪打中鬼魂约 10 秒后其身边会出现「不安的灵魂」，对它再补一枪即可拾取。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13289}, nil, 11140, "埃根", { xp = 8300, money = 18000 } },
        { 6163, "H", 56, 60, "纳萨诺斯·凋零者", "东瘟疫之地 22,68", "暗翼蝠", false, {6135}, {18022, 17001}, "到斯坦索姆击杀吞咽者拉姆斯登，把头颅交给纳萨诺斯。", "前置同样在纳萨诺斯处接。拉姆斯登在副本内。", {{56,2}, {58,3}, {63,4}, {72,5}}, {15880}, nil, 11878, "纳萨诺斯·凋零者", { xp = 6600, money = 18000, rep = { {68, 100, "幽暗城"} } } },
        { 5463, nil, 57, 60, "莱尼德·巴萨罗梅", "东瘟疫之地 - 圣光之愿礼拜堂 75,52", "亡灵莱斯·霜语", false, {5462}, nil, "到斯坦索姆找到米奈希尔的礼物，把巫妖生前的遗物放在那块邪恶的土地上。", "前置从马杜克镇长处接（西瘟疫之地 - 凯尔达隆 70,73）。标记就是男爵房间地上的五芒星。另见通灵学院的「巫妖莱斯·霜语」。", {{57,2}, {58,3}, {63,4}, {72,5}}, {13585}, nil, 11036, "莱尼德·巴萨罗梅", { xp = 6600 } },
        { 8945, nil, 58, 60, "伊思达·哈尔蒙", "东瘟疫之地 - 斯坦索姆", "寻找安泰恩", false, {8929}, {22137}, "进入斯坦索姆，从瑞文戴尔男爵手中救出伊思达。", "伊思达·哈尔蒙就站在副本门口，需要超维度幽灵显形器才能看到他。前置：联盟找德莉亚娜（铁炉堡 43,52），部落找莫克瓦尔（奥格瑞玛 38,37）。这也是著名的「45 分钟瑞文戴尔」任务。", {{58,3}, {63,4}, {72,5}}, nil, nil, 16016, "安泰恩·哈尔蒙", { xp = 8300 } },
        { 8968, nil, 58, 60, "伯德雷", "黑石山 副本入口地图中的[D]", "重要的材料", false, {8964}, nil, "用召唤火盆召出亚雷恩和索托斯的灵魂并杀掉他们，把火盆和瓦塔拉克饰品左瓣还给黑石山的伯德雷。", "需要超维度幽灵显形器才能看到伯德雷（从《寻找安泰恩》获得）。两人在副本内召唤。", {{58,3}, {63,4}, {72,5}}, {21984, 22051}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 8991, nil, 58, 60, "伯德雷", "黑石山 副本入口地图中的[D]", "更多重要的材料", false, {8987}, nil, "用召唤火盆召出亚雷恩和索托斯的灵魂并杀掉他们，把火盆和瓦塔拉克公爵的饰品还给黑石山的伯德雷。", "需要超维度幽灵显形器才能看到伯德雷（从《寻找安泰恩》获得）。两人在副本内召唤。", {{58,3}, {63,4}, {72,5}}, {22048, 22051}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 7622, nil, 60, nil, "艾瑞斯·哈文法", "东瘟疫之地 17,14", "警示", false, {7621}, nil, "在 15 个农夫被杀之前拯救 50 个农夫，完成后与艾瑞斯·哈文法谈谈。拯救进度可以看死亡布告。", "见到艾瑞斯·哈文法并接任务需要神圣之眼（火焰之王的宝箱，熔火之心出）。完成后把神圣之眼、诺达希尔碎片和暗影之眼（诅咒之地/冬泉谷随机恶魔掉落）组合，得到牧师史诗法杖——祈福。", {{60,3}, {63,4}, {72,5}}, nil, "牧师", 14494, "艾瑞斯·哈文法", nil },
        { 9257, nil, 60, nil, "阿纳克洛斯", "塔纳利斯 - 时光之穴 65,49", "埃提耶什，被玷污的传说之杖", false, {9251}, nil, "塔纳利斯时光之穴的阿纳克洛斯要你前往斯坦索姆，在神圣之地上使用埃提耶什、守护者的传说之杖，击败被驱赶出来的生物后回他那里复命。", "召唤位置在副本内。巫妖王之怒资料片中无法再获得此任务；只有「召唤出埃提耶什」这一步仍可完成。", {{60,3}, {63,4}, {72,5}}, {22737}, "牧师", nil, nil, nil },
